# Fix missing imports in sales/views.py for pos_vip_status
# Run from your dashboard folder (where manage.py is)

$base64 = ""
$bytes = [System.Convert]::FromBase64String($base64)
$py = [System.Text.Encoding]::UTF8.GetString($bytes)

# Backup
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
Copy-Item -Path "sales\views.py" -Destination "sales\views.py.importfix.$ts" -ErrorAction SilentlyContinue

# Write and run Python script
[IO.File]::WriteAllText("_temp_fix.py", $py)
python "_temp_fix.py"
Remove-Item "_temp_fix.py"

Write-Host "✅ Done! Missing imports added to sales/views.py" -ForegroundColor Green
Write-Host "Now run: python manage.py runserver" -ForegroundColor Cyan
